456	begin
457	
458		-- Reference CLK LED
459		LEDS(0) <= user_leds(2);
460		-- Lock status of PLLs
461		LEDS(1) <= clk_locked;
462		LEDS(2) <= LO1_LD;
463		LEDS(3) <= SOURCE_LD;
464		-- Sweep and active port
465		PORT_SELECT2 <= (sweep_excite_port2 and portswitch_en) when HW_overwrite_enabled = '0' else HW_overwrite_data(3);
466		PORT2_SELECT <= (sweep_excite_port2 and portswitch_en) when HW_overwrite_enabled = '0' else HW_overwrite_data(3);
467		PORT_SELECT1 <= (sweep_excite_port1 and portswitch_en) when HW_overwrite_enabled = '0' else HW_overwrite_data(4);
468		PORT1_SELECT <= (sweep_excite_port1 and portswitch_en) when HW_overwrite_enabled = '0' else HW_overwrite_data(4);
469		BAND_SELECT_HIGH <= not sweep_band when HW_overwrite_enabled = '0' else not HW_overwrite_data(5);
470		BAND_SELECT_LOW <= sweep_band when HW_overwrite_enabled = '0' else HW_overwrite_data(5);
471		PORT1_MIX2_EN <= port1mix_en;
472		PORT1_MIX1_EN <= not port1mix_en;
473		PORT2_MIX2_EN <= port2mix_en;
474		PORT2_MIX1_EN <= not port2mix_en;
475		REF_MIX2_EN <= refmix_en;
476		REF_MIX1_EN <= not refmix_en;
477		LEDS(4) <= not (not sweep_reset and sweep_excite_port2 and portswitch_en) when HW_overwrite_enabled = '0' else not HW_overwrite_data(3);
478		LEDS(5) <= not (not sweep_reset and sweep_excite_port1 and portswitch_en) when HW_overwrite_enabled = '0' else not HW_overwrite_data(4);
479		-- Uncommitted LEDs
480		LEDS(7 downto 6) <= user_leds(1 downto 0);	
481		--LEDS(7) <= '0';
482		MCU_INTR <= intr;
483		--LEDS(6) <= intr;
484		
485		MainCLK : PLL
486		port map(
487			-- Clock in ports
488			CLK_IN1 => CLK,
489			-- Clock out ports
490			CLK_OUT1 => clk_pll,
491			-- Status and control signals
492			RESET  => RESET,
493			LOCKED => clk_locked
494		);
495		
496		inv_clk_locked <= not clk_locked and not RESET;
497		
